package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import java.util.zip.ZipOutputStream;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.utils.BufferUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_read_TriageGen1Test {

    /**
     * Helper to create a valid ZIP byte array in memory
     */
    private byte[] createZipWithEntry(String content, boolean isStored) throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry("test.txt");
            if (isStored) {
                entry.setMethod(ZipEntry.STORED);
                entry.setSize(content.length());
                entry.setCrc(calculateCRC(content.getBytes()));
            }
            zos.putNextEntry(entry);
            zos.write(content.getBytes());
            zos.closeEntry();
        }
        return baos.toByteArray();
    }

    private long calculateCRC(byte[] data) {
        CRC32 crc = new CRC32();
        crc.update(data);
        return crc.getValue();
    }

    @Test(expected = IOException.class)
    public void testRead_ClosedStream() throws IOException {
        byte[] zipData = createZipWithEntry("hello", false);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();
        zais.close();
        zais.read(new byte[10], 0, 5);
    }

    @Test
    public void testRead_FinishedOrNullEntry() throws IOException {
        byte[] zipData = createZipWithEntry("hello", false);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        // No entry selected yet (current == null)
        Assert.assertEquals(-1, zais.read(new byte[10], 0, 5));

        zais.getNextZipEntry();
        zais.close();
        // Stream finished
        Assert.assertEquals(-1, zais.read(new byte[10], 0, 5));
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_InvalidBufferBounds() throws IOException {
        byte[] zipData = createZipWithEntry("hello", false);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();
        // start > buffer.length
        zais.read(new byte[5], 10, 1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_NegativeStart() throws IOException {
        byte[] zipData = createZipWithEntry("hello", false);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();
        zais.read(new byte[5], -1, 1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_NegativeLength() throws IOException {
        byte[] zipData = createZipWithEntry("hello", false);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();
        zais.read(new byte[5], 0, -1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_BufferOverflow() throws IOException {
        byte[] zipData = createZipWithEntry("hello", false);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();
        // buffer.length - start < length
        zais.read(new byte[5], 2, 4);
    }

    @Test
    public void testRead_StoredMethod_FullRead() throws IOException {
        String content = "storeddata";
        byte[] zipData = createZipWithEntry(content, true);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();

        byte[] buffer = new byte[20];
        int read = zais.read(buffer, 0, content.length());

        Assert.assertEquals(content.length(), read);
        Assert.assertEquals(content, new String(buffer, 0, read));
    }

    @Test
    public void testRead_StoredMethod_ChunkedRead() throws IOException {
        String content = "chunkeddata";
        byte[] zipData = createZipWithEntry(content, true);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();

        byte[] buffer = new byte[20];
        // First read small chunk
        int read1 = zais.read(buffer, 0, 4);
        Assert.assertEquals(4, read1);
        Assert.assertEquals("chun", new String(buffer, 0, 4));

        // Second read triggers offsetInBuffer logic
        int read2 = zais.read(buffer, 4, 4);
        Assert.assertEquals(4, read2);
        Assert.assertEquals("keda", new String(buffer, 4, 4));

        // Third read triggers new in.read(buf)
        int read3 = zais.read(buffer, 8, 3);
        Assert.assertEquals(3, read3);
        Assert.assertEquals("ta", new String(buffer, 8, 2)); // Adjusted for remaining
    }

    @Test
    public void testRead_DeflatedMethod_Normal() throws IOException {
        String content = "deflateddata";
        byte[] zipData = createZipWithEntry(content, false);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();

        byte[] buffer = new byte[20];
        int read = zais.read(buffer, 0, content.length());

        Assert.assertEquals(content.length(), read);
        Assert.assertEquals(content, new String(buffer, 0, read));
    }

    @Test
    public void testRead_DeflatedMethod_Truncated() throws IOException {
        // Creating a truncated stream by cutting off bytes
        byte[] zipData = createZipWithEntry("some long content", false);
        byte[] truncated = new byte[zipData.length - 5];
        System.arraycopy(zipData, 0, truncated, 0, truncated.length);

        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(truncated));
        zais.getNextZipEntry();

        byte[] buffer = new byte[20];
        // This might trigger the "Truncated ZIP file" IOException depending on where the cut is
        try {
            zais.read(buffer, 0, 20);
        } catch (IOException e) {
            Assert.assertTrue(e.getMessage().contains("Truncated") || e.getMessage().contains("ZIP"));
        }
    }
}
